// @test-kind contract: how Lense aligns a served portal document with the exported markup sources: which start tags it names as a source's own, which as generated by a source's Liquid code, which as the portal's shell, and when it refuses to choose
import test from 'node:test';
import assert from 'node:assert/strict';
import {
  alignDocument,
  alignResponse,
  indexPrepared,
  prepareAlignment,
  scanLiquidTokens,
  sourceItems,
} from '../lense/response-alignment.mjs';
import { buildPortalSourceIndex } from '../mirage/lib/portal-source-index.mjs';

const prepare = (sources) =>
  indexPrepared(prepareAlignment(Object.entries(sources).map(([id, text]) => ({ id, text, name: id, tier: 0 }))));
const align = (html, sources, options) => {
  const result = alignResponse(html, prepare(sources), options);
  return result.bindings.map((binding) => ({
    tag: html.slice(binding.start, binding.end),
    mapping: binding.mapping,
    source: binding.sourceRefId ?? binding.sourceRefIds?.join('|') ?? null,
    region: binding.region && sources[binding.sourceRefId]?.slice(binding.region.start, binding.region.end),
    placement: binding.placement,
    dynamic: binding.dynamic,
    contexts: binding.contexts.map(
      (context) =>
        context.sourceRefId + ':' + sources[context.sourceRefId].slice(context.region.start, context.region.end),
    ),
  }));
};
const of = (rows, tag) => rows.find((row) => row.tag.startsWith(tag));

test('a Liquid token ends at its closer outside quotes and a comment hides what it holds', () => {
  const tokens = scanLiquidTokens(
    `{% include 'Card' width: '50%}' %}<b>{{ "a }} b" | upcase }}</b>{% comment %}<i>{{ x }}</i>{% endcomment %}{% raw %}{{ kept }}{% endraw %}`,
  );
  assert.deepEqual(
    tokens.map((token) => [token.kind, token.name]),
    [
      ['tag', 'include'],
      ['output', ''],
      ['tag', 'comment'],
      ['tag', 'raw'],
      ['tag', 'endraw'],
    ],
  );
  const { items } = sourceItems('{% comment %}<i>hidden</i>{% endcomment %}{% raw %}<u>{{ kept }}</u>{% endraw %}');
  assert.deepEqual(
    items.filter((item) => item.t === 'start').map((item) => item.name),
    ['u'],
    'a comment writes nothing; a raw block writes its text as it stands',
  );
});

test('literal markup is found where the source puts it, whatever the portal changed in spelling', () => {
  const sources = {
    Main: '<section class="hero" id="top">\n  <h1>Build it three ways.<br />Understand it.</h1>\n  <a href="/start/" class="go">Open &amp; read</a>\n</section>',
  };
  // Served: a self-closing solidus dropped, an entity spelled another way, attributes in another order, a nonce added.
  const html =
    '<html><body><section id="top" class="hero">\n<h1>Build it three ways.<br>Understand it.</h1>' +
    '<a class="go" href="/start/" nonce="n1">Open &#38; read</a></section></body></html>';
  const rows = align(html, sources);
  assert.deepEqual(
    rows.map((row) => [row.mapping, row.region ?? null]),
    [
      ['shell', null],
      ['shell', null],
      ['aligned', '<section class="hero" id="top">'],
      ['aligned', '<h1>'],
      ['aligned', '<br />'],
      ['aligned', '<a href="/start/" class="go">'],
    ],
  );
});

test('a start tag with Liquid inside it is the source tag, marked as carrying server output', () => {
  const sources = { Main: '<div class="card"><a href="{{ page.url }}" class="more">Read the article</a></div>' };
  const rows = align('<div class="card"><a href="/news/42/" class="more">Read the article</a></div>', sources);
  assert.deepEqual(
    [of(rows, '<a').mapping, of(rows, '<a').region, of(rows, '<a').dynamic],
    ['aligned', '<a href="{{ page.url }}" class="more">', true],
  );
  // The static attribute must still be the source's: another class is another tag.
  const other = align('<div class="card"><a href="/news/42/" class="less">Read the article</a></div>', sources);
  assert.notEqual(of(other, '<a').mapping, 'aligned');
});

test('what stands between two parts of a source was written by the Liquid code between them', () => {
  const sources = {
    Layout:
      '<main id="content" class="wrapper">\n  <div class="page-copy">{% editable page \'adx_copy\' type: \'html\' %}</div>\n</main>',
    Copy: '<p class="lead">Welcome to the invented portal</p>',
  };
  const html =
    '<main id="content" class="wrapper"><div class="page-copy"><div class="xrm-editable-html"><div class="xrm-attribute-value">' +
    '<p class="lead">Welcome to the invented portal</p></div></div></div></main>';
  const rows = align(html, sources);
  const wrapper = of(rows, '<div class="xrm-editable-html">');
  assert.deepEqual(
    [wrapper.mapping, wrapper.source, wrapper.region],
    ['generated', 'Layout', "{% editable page 'adx_copy' type: 'html' %}"],
  );
  // Knowing that the tag prints Copy changes nothing: Copy names its own tags here, the wrapper stays the tag's.
  const resolved = alignResponse(html, prepare(sources), { resolve: () => 'Copy' }).bindings.find((binding) =>
    html.slice(binding.start).startsWith('<div class="xrm-editable-html">'),
  );
  assert.deepEqual(
    [resolved.mapping, resolved.sourceRefId, sources.Layout.slice(resolved.region.start, resolved.region.end)],
    ['generated', 'Layout', "{% editable page 'adx_copy' type: 'html' %}"],
  );
  const lead = of(rows, '<p class="lead">');
  assert.deepEqual([lead.mapping, lead.source], ['aligned', 'Copy']);
  assert.deepEqual(
    lead.contexts,
    ["Layout:{% editable page 'adx_copy' type: 'html' %}"],
    'the copy is named with what printed it',
  );
});

test('a loop body is placed once per item, by its depth between two placed parts of its source', () => {
  const sources = {
    Nav: '<ul class="nav primary">{% for link in links %}<li><a href="{{ link.url }}">{{ link.html }}</a></li>{% endfor %}</ul>',
  };
  // The second item prints a list of its own inside the link: its <li> is deeper than the loop writes its own.
  const html =
    '<ul class="nav primary"><li><a href="/a/">A</a></li><li><a href="/b/"><ul><li>printed</li></ul></a></li><li><a href="/c/">C</a></li></ul>';
  const rows = align(html, sources);
  assert.deepEqual(
    rows.filter((row) => row.tag === '<li>').map((row) => [row.mapping, row.source, row.region ?? null]),
    [
      ['aligned', 'Nav', '<li>'],
      ['aligned', 'Nav', '<li>'],
      ['generated', 'Nav', '{{ link.html }}'],
      ['aligned', 'Nav', '<li>'],
    ],
  );
  assert.deepEqual(
    rows.filter((row) => row.tag.startsWith('<a ')).map((row) => [row.mapping, row.region]),
    [
      ['aligned', '<a href="{{ link.url }}">'],
      ['aligned', '<a href="{{ link.url }}">'],
      ['aligned', '<a href="{{ link.url }}">'],
    ],
  );
});

test('outside a loop a bare tag that fits in several places is not placed', () => {
  const sources = {
    Box: '<div class="box" id="b">{{ intro }}<p>{{ first }}</p><span class="end" id="e">done</span></div>',
  };
  const html = '<div class="box" id="b"><p>one</p><p>two</p><span class="end" id="e">done</span></div>';
  const rows = align(html, sources);
  assert.deepEqual(
    rows.filter((row) => row.tag === '<p>').map((row) => [row.mapping, row.region]),
    [
      ['generated', '{{ intro }}<p>{{ first }}'],
      ['generated', '{{ intro }}<p>{{ first }}'],
    ],
    'neither <p> is shown to be the one the source writes: both stand in what the code between the two tags wrote',
  );
});

test('markup the served page holds where the local source holds nothing is the deployed copy differing', () => {
  const sources = {
    Card: '<div class="card" id="c"><h2 class="title">Invented card title</h2><p class="text">Body</p></div>',
  };
  const html =
    '<div class="card" id="c"><h2 class="title">Invented card title</h2><img src="/old.png"><p class="text">Body</p></div>';
  const rows = align(html, sources);
  const image = of(rows, '<img');
  assert.deepEqual([image.mapping, image.source, image.region], ['drift', 'Card', '']);
  assert.equal(rows.filter((row) => row.mapping === 'aligned').length, 3);
});

test('two sources that explain a tag equally are a conflict; the page own source wins a tie by its tier', () => {
  const text = '<div class="promo" id="spring"><p class="promo-text">Spring offer for members</p></div>';
  const html = '<body>' + text + '</body>';
  const tie = alignResponse(html, prepare({ One: text, Two: text }));
  assert.deepEqual(
    tie.bindings.filter((binding) => binding.tag !== 'body').map((binding) => binding.mapping),
    ['conflict', 'conflict'],
  );
  assert.deepEqual(tie.bindings[1].sourceRefIds.toSorted(), ['One', 'Two']);
  const ranked = alignResponse(html, prepare({ One: text, Two: text }), {
    tiers: new Map([
      ['Two', 0],
      ['One', 1],
    ]),
  });
  assert.deepEqual(
    ranked.bindings
      .filter((binding) => binding.tag !== 'body')
      .map((binding) => [binding.mapping, binding.sourceRefId]),
    [
      ['aligned', 'Two'],
      ['aligned', 'Two'],
    ],
  );
});

test('a longer match around a tag explains it better than a shorter one', () => {
  const sources = {
    Long: '<div class="row"><div class="col"><h2 class="title">Latest invented news</h2><p class="intro">Read on</p></div></div>',
    Short: '<div class="row"><div class="col">{{ x }}</div></div>',
  };
  const html =
    '<div class="row"><div class="col"><h2 class="title">Latest invented news</h2><p class="intro">Read on</p></div></div>';
  assert.deepEqual([...new Set(align(html, sources).map((row) => row.source))], ['Long']);
});

test('markup the served page does not hold is not attributed: a source whose deployed copy differs leaves its tags unnamed', () => {
  const sources = {
    Banner: '<aside class="banner new" id="notice"><strong class="headline">Edited locally</strong></aside>',
  };
  const html = '<body><aside class="banner" id="notice"><strong class="headline">As deployed</strong></aside></body>';
  const result = alignResponse(html, prepare(sources));
  assert.deepEqual(
    result.bindings.map((binding) => binding.mapping),
    ['shell', 'shell', 'shell'],
  );
  assert.deepEqual(result.coverage, [], 'no tag of the source was found');
  assert.deepEqual(result.counts, { aligned: 0, bracketed: 0, generated: 0, drift: 0, shell: 3, conflict: 0 });
});

test('a reference that prints a source without markup of its own is followed to that source', () => {
  const sources = {
    Layout: '<main id="content" class="wrapper"><div class="page-copy">{% include \'Body\' %}</div></main>',
    Body: "{% entityform name: 'Invented request' %}",
  };
  const html =
    '<main id="content" class="wrapper"><div class="page-copy"><div id="EntityFormControl"><input id="name"></div></div></main>';
  const prepared = prepare(sources);
  const result = alignResponse(html, prepared, { resolve: (token) => (token.name === 'include' ? 'Body' : null) });
  const form = result.bindings.find((binding) => binding.tag === 'input');
  assert.deepEqual(
    [form.mapping, form.sourceRefId, sources.Body.slice(form.region.start, form.region.end)],
    ['generated', 'Body', "{% entityform name: 'Invented request' %}"],
  );
  assert.deepEqual(
    form.contexts.map((context) => context.sourceRefId),
    ['Layout'],
  );
  assert.deepEqual(form.liquid, [{ kind: 'tag', name: 'entityform' }]);
});

test('an imported portal aligns by its own index: the requested page copy wins over another page with the same markup', () => {
  const copy = '<div class="intro" id="lead"><p class="hello">Hello from an invented page</p></div>';
  const page = (id, url) => ({
    id,
    url,
    html: copy,
    pageTemplateId: 'page-layout',
    metadata: { id, kind: 'webpage', name: id },
    translations: {},
  });
  const template = { id: 'layout', kind: 'webtemplate', name: 'Layout' };
  const source = '<main id="content" class="wrapper">{{ page.adx_copy }}</main>';
  const portal = {
    sourceDir: null,
    website: {},
    records: [],
    templates: { Layout: { id: 'layout', name: 'Layout', metadata: template, source } },
    pageTemplates: [{ id: 'page-layout', name: 'Layout', webTemplateId: 'layout', useHeaderFooter: false }],
    snippets: {},
    pages: [page('first', '/first/'), page('second', '/second/')],
  };
  const index = buildPortalSourceIndex({ portal });
  const html = '<html><body><main id="content" class="wrapper">' + copy + '</main></body></html>';
  const aligned = alignDocument(html, index, '/second');
  const lead = [...aligned.byStart.values()].find((binding) => binding.tag === 'div');
  assert.equal(lead.mapping, 'aligned');
  assert.equal(index.sources.get(lead.sourceRefId).recordId, 'second');
  assert.deepEqual(
    lead.contexts.map((context) => source.slice(context.region.start, context.region.end)),
    ['{{ page.adx_copy }}'],
  );
  assert.deepEqual(aligned.counts, { aligned: 3, bracketed: 0, generated: 0, drift: 0, shell: 2, conflict: 0 });
});

test('identical markup in several places of one source is taken in source order, or left without a line when the page shows only some of them', () => {
  const note = '<p class="note" id="terms">Read the invented terms</p>';
  const sources = {
    Notes: `{% if a %}\n${note}\n{% endif %}\n<hr class="rule" id="rule">\n{% if b %}\n${note}\n{% endif %}\n`,
  };
  const second = sources.Notes.lastIndexOf(note);
  const both = alignResponse(`${note}<hr class="rule" id="rule">${note}`, prepare(sources));
  assert.deepEqual(
    both.bindings.filter((binding) => binding.tag === 'p').map((binding) => [binding.region.start, binding.oneOf]),
    [
      [sources.Notes.indexOf(note), undefined],
      [second, undefined],
    ],
  );
  // Only one of the two branches rendered, and nothing else of the source says which.
  const one = alignResponse(`<main>${note}</main>`, prepare(sources));
  const shown = one.bindings.find((binding) => binding.tag === 'p');
  assert.deepEqual([shown.mapping, shown.sourceRefId, shown.oneOf], ['aligned', 'Notes', 2]);
});

// ---- another version of a source than the local one: where the served document and the source disagree

const differences = (html, sources, options) =>
  alignResponse(html, prepare(sources), options).differences.map((difference) => ({
    source: difference.sourceRefId,
    kind: difference.kind,
    local: sources[difference.sourceRefId].slice(difference.region.start, difference.region.end),
    served: html.slice(difference.served.start, difference.served.end),
    ...(difference.open ? { open: true } : {}),
    ...(difference.exact ? { exact: true } : {}),
  }));

test('markup a source spells out is compared between its tags found: what only one side holds, and what differs', () => {
  const sources = {
    Header:
      '<header id="top" class="site-header"><span class="brand" id="brand">New brand</span><nav id="nav" class="main"><a class="item" href="/a/">A</a><a class="item new" href="/c/">C</a></nav></header>',
  };
  const html =
    '<body><header id="top" class="site-header"><a class="skip" href="#main">Skip</a><span class="brand" id="brand">Old brand</span><nav id="nav" class="main"><a class="item" href="/a/">A</a></nav></header></body>';
  assert.deepEqual(differences(html, sources), [
    { source: 'Header', kind: 'served-only', local: '', served: '<a class="skip" href="#main">Skip</a>' },
    { source: 'Header', kind: 'changed', local: 'New brand', served: 'Old brand' },
    { source: 'Header', kind: 'local-only', local: '<a class="item new" href="/c/">C</a>', served: '' },
  ]);
  // The tag only the served document holds is not in the local file: it is named as that, at the place it would stand.
  const skip = of(align(html, sources), '<a class="skip"');
  assert.deepEqual([skip.mapping, skip.source], ['drift', 'Header']);
  // The same document against the version it was rendered from differs nowhere.
  const deployed = {
    Header:
      '<header id="top" class="site-header"><a class="skip" href="#main">Skip</a><span class="brand" id="brand">Old brand</span><nav id="nav" class="main"><a class="item" href="/a/">A</a></nav></header>',
  };
  assert.deepEqual(differences(html, deployed), []);
});

test('Liquid code between two tags hides what differs there, unless it only decides', () => {
  // An output can print anything: what stands after it is not compared.
  const printing = {
    Card: '<div class="card" id="card"><h3 class="title">{{ title }}</h3><p class="more" id="more">Local text</p></div>',
  };
  assert.deepEqual(
    differences(
      '<div class="card" id="card"><h3 class="title">Hello</h3><p class="more" id="more">Served text</p></div>',
      printing,
    ),
    [{ source: 'Card', kind: 'changed', local: 'Local text', served: 'Served text' }],
  );
  // Conditions and loops write nothing of their own: whatever the document holds between them is one of the literals.
  const deciding = {
    Menu: '<ul class="menu" id="menu">{% if user %}<li class="out"><a class="link" href="/out">Sign out</a></li>{% else %}<li class="in"><a class="link" href="/in">Sign in</a></li>{% endif %}</ul>',
  };
  assert.deepEqual(
    differences('<ul class="menu" id="menu"><li class="in"><a class="link" href="/in">Sign in</a></li></ul>', deciding),
    [],
  );
  // An element found whole (no Liquid code inside it) is compared like any literal stretch.
  assert.deepEqual(
    differences(
      '<ul class="menu" id="menu"><li class="in"><a class="link" href="/login">Log in</a></li></ul>',
      deciding,
    ),
    [
      {
        source: 'Menu',
        kind: 'changed',
        local: '<a class="link" href="/in">Sign in',
        served: '<a class="link" href="/login">Log in',
      },
    ],
  );
  // A tag that is none of the literals between the conditions was written by another version of the source.
  const other = differences(
    '<ul class="menu" id="menu"><li class="guest"><a class="link" href="/in">Sign in</a></li></ul>',
    deciding,
  );
  assert.deepEqual(
    other.map((difference) => [difference.kind, difference.served, difference.open, difference.exact]),
    [['changed', '<li class="guest">', true, true]],
  );
});

test('the portal closing an element a template leaves open, or dropping a stray end tag, is no other version', () => {
  const sources = {
    Footer: '<footer id="foot" class="footer"><div class="inner" id="inner"><p class="c" id="c">Text</p></footer>',
  };
  assert.deepEqual(
    differences(
      '<footer id="foot" class="footer"><div class="inner" id="inner"><p class="c" id="c">Text</p></div></footer>',
      sources,
    ),
    [],
  );
});

test('an attribute or a piece of an attribute value inside a Liquid block may be served or not', () => {
  const sources = {
    Nav: `<nav id="nav" class="bar {% if wide %}wide{% endif %}"><a class="item" href="/one/"{% if here == 'one' %} aria-current="page"{% endif %}>One</a><a class="item" href="/two/"{% if here == 'two' %} aria-current="page"{% endif %}>Two</a></nav>`,
  };
  const html =
    '<nav id="nav" class="bar "><a class="item" href="/one/">One</a><a class="item" href="/two/" aria-current="page">Two</a></nav>';
  const rows = align(html, sources);
  assert.deepEqual(
    rows.map((row) => [row.mapping, row.source, row.dynamic]),
    [
      ['aligned', 'Nav', true],
      ['aligned', 'Nav', true],
      ['aligned', 'Nav', true],
    ],
  );
  assert.deepEqual(differences(html, sources), []);
  assert.deepEqual(differences(html.replace('class="bar "', 'class="bar wide"'), sources), []);
});

test('short markup that merely looks like a source is not that source: the document goes on differently beside it', () => {
  const sources = {
    Header:
      '<header id="top" class="site"><nav id="nav" class="main"><a href="/">Home</a><a href="/docs/">Docs</a></nav></header>',
    Crumbs: `<ul class="breadcrumb">{% for crumb in page.breadcrumbs %}<li class="crumb"><a href="{{ crumb.url }}" title="{{ crumb.title }}">{{ crumb.title }}</a></li>{% endfor %}</ul>`,
  };
  // The portal's own breadcrumb: the same list classes, links without a title, and a link that also stands in the header.
  const html =
    '<header id="top" class="site"><nav id="nav" class="main"><a href="/">Home</a><a href="/docs/">Docs</a></nav></header>' +
    '<ul class="breadcrumb"><li class="crumb"><a href="/">Home</a></li><li class="crumb active">Here</li></ul>';
  const rows = align(html, sources);
  const crumbs = rows.slice(rows.findIndex((row) => row.tag.startsWith('<ul')));
  assert.deepEqual(
    crumbs.map((row) => row.mapping),
    ['shell', 'shell', 'shell', 'shell'],
  );
  assert.deepEqual(differences(html, sources), []);
});

test('a source the page is not seen to reach is named only by a long sequence, and never before the page’s own', () => {
  const own =
    '<section class="hero" id="hero"><h1 class="title">Welcome</h1><p class="lead" id="lead">Served lead</p><p class="note" id="note">Shared note</p></section>';
  const local = own.replace('Served lead', 'Local lead');
  const prepared = (sources) =>
    indexPrepared(prepareAlignment(Object.entries(sources).map(([id, text]) => ({ id, text, name: id }))));
  const tiers = new Map([
    ['Page', 0],
    ['Other', 2],
  ]);
  // Another page holds the served text: its sequence is longer than the changed page's own, and still not the answer.
  const result = alignResponse(`<main>${own}</main>`, prepared({ Page: local, Other: own }), { tiers });
  assert.deepEqual([...new Set(result.bindings.map((binding) => binding.sourceRefId).filter(Boolean))], ['Page']);
  assert.deepEqual(
    result.differences.map((difference) => [difference.sourceRefId, difference.kind]),
    [['Page', 'changed']],
  );
  // A lone tag of a source out of reach names nothing.
  const lone = alignResponse('<main><p class="note" id="note">x</p></main>', prepared({ Other: own }), { tiers });
  assert.deepEqual(
    lone.bindings.map((binding) => binding.mapping),
    ['shell', 'shell'],
  );
});

test('one version of a source can stand in for another: the working copy is left out and the other compared', () => {
  const working =
    '<aside class="banner" id="notice"><strong class="headline" id="h">Edited locally</strong><em class="tag" id="t">new</em></aside>';
  const baseline = '<aside class="banner" id="notice"><strong class="headline" id="h">As deployed</strong></aside>';
  const html = `<body>${baseline}</body>`;
  const prepared = indexPrepared(
    prepareAlignment([
      { id: 'Banner', text: working, tier: 0 },
      { id: 'baseline:Banner', text: baseline, tier: 0 },
    ]),
  );
  const result = alignResponse(html, prepared, { exclude: ['Banner'] });
  assert.deepEqual(result.differences, []);
  assert.deepEqual(
    [...new Set(result.bindings.map((binding) => binding.sourceRefId).filter(Boolean))],
    ['baseline:Banner'],
  );
  const against = alignResponse(html, prepared, { exclude: ['baseline:Banner'] });
  assert.deepEqual(
    against.differences.map((difference) => difference.kind),
    ['changed', 'local-only'],
  );
});

test('what a capture body holds is not compared: the page may show it changed on the way', () => {
  const sources = {
    Card: `<div class="card" id="card">{% capture label %}<b class="label" id="label">hello there</b>{% endcapture %}{{ label | replace: 'hello', 'goodbye' }}</div>`,
  };
  const html = '<div class="card" id="card"><b class="label" id="label">goodbye there</b></div>';
  const result = alignResponse(html, prepare(sources));
  assert.deepEqual(result.differences, []);
});

// ---- dynamic Liquid: what the render oracle (mirage/test/alignment-render-differential.test.mjs) showed

test('a fetchxml query and a manifest write nothing: their bodies are no markup of the source', () => {
  const sources = {
    Preview:
      '<section class="panel" id="panel"><h2 class="heading">Accounts</h2>{% if user %}{% fetchxml rows %}<fetch count="{{ n }}"><entity name="account"><attribute name="name"/></entity></fetch>{% endfetchxml %}<div class="cards">{% for row in rows.results.entities %}{% include \'Card\' %}{% endfor %}</div>{% endif %}</section>{% manifest %}{"type":"Functional","params":[]}{% endmanifest %}',
  };
  assert.deepEqual(
    sourceItems(sources.Preview)
      .items.filter((item) => item.t === 'start')
      .map((item) => item.name),
    ['section', 'h2', 'div'],
  );
  const rows = align(
    '<main><section class="panel" id="panel"><h2 class="heading">Accounts</h2><div class="cards"></div></section></main>',
    sources,
  );
  assert.deepEqual(
    [of(rows, '<div class="cards">').mapping, of(rows, '<div class="cards">').region],
    ['aligned', '<div class="cards">'],
    'the loop container after the query is the source tag, its empty loop or not',
  );
});

test('Liquid code between two literals that both differ is not laid over: what it printed is no served-only markup', () => {
  const sources = {
    Banner:
      '<section class="banner" id="banner"><h2 class="banner-title" id="banner-title">Title</h2><!-- lead -->New lead<!-- body -->{{ page.title }}<!-- foot -->New foot<footer class="foot" id="foot"><a class="more" href="/more">More</a></footer></section>',
  };
  const html =
    '<body><section class="banner" id="banner"><h2 class="banner-title" id="banner-title">Title</h2><!-- lead -->Old lead<!-- body -->Printed by the portal<!-- foot -->Old foot<footer class="foot" id="foot"><a class="more" href="/more">More</a></footer></section></body>';
  const found = differences(html, sources);
  assert.ok(found.length > 0);
  assert.ok(
    found.every((difference) => difference.open && !difference.served.includes('Printed by the portal')),
    JSON.stringify(found),
  );
});

test('a tag that writes nothing inside one text node leaves the node whole: no false difference', () => {
  const comment = { Banner: '<p class="t" id="t">Contact us {% comment %}phone later{% endcomment %}today</p>' };
  assert.deepEqual(differences('<body><p class="t" id="t">Contact us today</p></body>', comment), []);
  const assigned = { Banner: '<p class="t" id="t">Hello {%- assign x = 1 -%} world</p><hr class="r" id="r">' };
  assert.deepEqual(differences('<body><p class="t" id="t">Helloworld</p><hr class="r" id="r"></body>', assigned), []);
  assert.equal(of(align('<p class="t" id="t">Contact us today</p>', comment), '<p').mapping, 'aligned');
});

test('text at the very start or end of a source may share its served text node with what stands beside it', () => {
  const tail = { Credit: '<b class="brand" id="brand">Invented Co</b> builds this' };
  assert.deepEqual(
    differences('<p class="x"><b class="brand" id="brand">Invented Co</b> builds this and partners</p>', tail),
    [],
  );
  const head = { Credit: 'the team at <a class="team" href="/team/">Invented Co</a>' };
  assert.deepEqual(
    differences('<p class="x">Made by the team at <a class="team" href="/team/">Invented Co</a></p>', head),
    [],
  );
});

test('a source whose top-level markup is not on the page is reported unrooted and still names the tags it matched', () => {
  const card =
    '<div class="card" id="news"><h3 class="card-title">Latest news</h3><p class="card-text">Read all about it</p></div>';
  const sources = { Area: `<section class="first" id="first-area">${card}</section>` };
  const inside = alignResponse(`<main class="shell-main">${card}</main>`, prepare(sources));
  assert.deepEqual(
    inside.coverage.map((row) => [row.sourceRefId, row.rooted]),
    [['Area', false]],
  );
  // The outer element is what a deployed version may change (the live captures show a built-in template whose root
  // the portal updated): the inner tags stay named, and the caller decides what an unrooted source may change.
  assert.deepEqual(
    inside.bindings.filter((binding) => binding.mapping === 'aligned').map((binding) => binding.tag),
    ['div', 'h3', 'p'],
  );
  const whole = alignResponse(
    `<main class="shell-main"><section class="first" id="first-area">${card}</section></main>`,
    prepare(sources),
  );
  assert.deepEqual(
    whole.coverage.map((row) => [row.sourceRefId, row.rooted]),
    [['Area', true]],
  );
});

test('markup a source repeats many times is aligned in time and memory linear in practice, never thrown away', () => {
  const row = '<tr class="r"><td class="c"><input type="checkbox" class="chk"></td></tr>';
  const source = '<table id="t" class="grid"><tbody>' + row.repeat(2000) + '</tbody></table>';
  const result = alignResponse('<html><body>' + source + '</body></html>', prepare({ Grid: source }));
  assert.equal(result.truncated, false);
  assert.equal(result.counts.aligned, 6002, 'every tag of every row is the row of the same position');
  const lines = result.bindings.filter((binding) => binding.tag === 'tr').map((binding) => binding.region.start);
  assert.deepEqual(lines.slice(0, 3), [34, 34 + row.length, 34 + 2 * row.length]);
});

test('two sources that hold a tag equally, inside what Liquid code of a placed source wrote, leave the answer to that code', () => {
  const options =
    '<select class="pick" id="pick"><option value="1">One</option><option value="2">Two</option></select>';
  const sources = {
    Page: '<main id="content" class="wrapper"><h1 class="title">Request</h1>{% entityform name: \'Invented request\' %}<p class="note" id="note">Thanks</p></main>',
    OtherCopy: `<div class="copy" id="copy">${options}</div>`,
    OtherCopyFr: `<div class="copy" id="copy">${options}</div>`,
  };
  const html = `<main id="content" class="wrapper"><h1 class="title">Request</h1><form id="f">${options}</form><p class="note" id="note">Thanks</p></main>`;
  const result = alignResponse(html, prepare(sources), {
    tiers: new Map([
      ['Page', 0],
      ['OtherCopy', 2],
      ['OtherCopyFr', 2],
    ]),
  });
  const option = result.bindings.find((binding) => binding.tag === 'option');
  assert.deepEqual(
    [option.mapping, option.sourceRefId, sources.Page.slice(option.region.start, option.region.end)],
    ['generated', 'Page', "{% entityform name: 'Invented request' %}"],
  );
  assert.equal(result.counts.conflict, 0);
  // Without code of a placed source around it, the tie stays a conflict.
  assert.equal(alignResponse(`<body>${options}</body>`, prepare(sources)).counts.conflict > 0, true);
});

test('the same markup in two branches of a condition is one of two places: the run does not step from one branch into the next', () => {
  const sources = {
    Section: [
      '<section class="c" id="c">',
      '{% case page.title %}{% when \'Alpha\' %}<span class="k">first</span>{% else %}<span class="k">other</span>{% endcase %}',
      '{% if user %}<p class="same">Shared line</p>{% else %}<p class="same">Shared line</p>{% endif %}',
      '<ul class="tail" id="tail"><li class="t">End</li></ul>',
      '</section>',
    ].join('\n'),
  };
  const html =
    '<main><section class="c" id="c">\n<span class="k">first</span>\n<p class="same">Shared line</p>\n<ul class="tail" id="tail"><li class="t">End</li></ul>\n</section></main>';
  const same = alignResponse(html, prepare(sources)).bindings.find((binding) => binding.tag === 'p');
  // Whichever branch rendered, the page holds the same markup: the file is known, the line is one of two.
  assert.deepEqual([same.mapping, same.sourceRefId, same.oneOf], ['aligned', 'Section', 2]);
  // A branch whose first tag differs is followed into: the run crosses `else` to the branch the page shows.
  const branches = {
    Menu: '<ul class="m" id="m">{% if user %}<li class="out">Sign out</li>{% else %}<li class="in">Sign in</li>{% endif %}<li class="help" id="help">Help</li></ul>',
  };
  const rows = align(
    '<ul class="m" id="m"><li class="in">Sign in</li><li class="help" id="help">Help</li></ul>',
    branches,
  );
  assert.deepEqual(
    [of(rows, '<li class="in"').mapping, of(rows, '<li class="in"').region],
    ['aligned', '<li class="in">'],
  );
});

test('short markup of the page’s own copy is named although the same page holds it in another language', () => {
  const copy = '<p class="gamma-copy">Gamma shows a form.</p>';
  const prepared = indexPrepared(
    prepareAlignment([
      { id: 'Layout', text: '<main id="content" class="wrapper">{{ page.adx_copy }}</main>', tier: 0 },
      { id: 'Copy', text: copy, tier: 0 },
      { id: 'CopyOtherLanguage', text: copy, tier: 1 },
    ]),
  );
  const result = alignResponse(`<main id="content" class="wrapper">${copy}</main>`, prepared);
  const lead = result.bindings.find((binding) => binding.tag === 'p');
  assert.deepEqual([lead.mapping, lead.sourceRefId], ['aligned', 'Copy']);
  // Two sources the page prints holding it: neither is named by so short a sequence.
  const both = indexPrepared(
    prepareAlignment([
      { id: 'Layout', text: '<main id="content" class="wrapper">{{ page.adx_copy }}</main>', tier: 0 },
      { id: 'Copy', text: copy, tier: 0 },
      { id: 'Snippet', text: copy, tier: 0 },
    ]),
  );
  assert.notEqual(
    alignResponse(`<main id="content" class="wrapper">${copy}</main>`, both).bindings.find(
      (binding) => binding.tag === 'p',
    ).mapping,
    'aligned',
  );
});

test('the items of a loop between a tag of its first item and a tag of its last are each the loop body', () => {
  const sources = {
    Colors:
      '<ul class="colors" id="colors">{% for color in colors %}<li class="color{% if forloop.first %} first{% endif %}{% if forloop.last %} last{% endif %}">{{ color }}{% if forloop.last %}<em class="end">end</em>{% endif %}</li>{% endfor %}</ul>',
  };
  const html =
    '<ul class="colors" id="colors"><li class="color first">red</li><li class="color">green</li><li class="color">blue</li><li class="color last">amber<em class="end">end</em></li></ul>';
  const items = align(html, sources).filter((row) => row.tag.startsWith('<li'));
  assert.deepEqual(
    items.map((row) => [row.mapping, row.source]),
    [
      ['aligned', 'Colors'],
      ['aligned', 'Colors'],
      ['aligned', 'Colors'],
      ['aligned', 'Colors'],
    ],
  );
});

test('a literal tag of a template that an include printed is that tag, though the template placed nothing else', () => {
  const sources = {
    Grid: '<table class="grid" id="grid"><tbody>{% for row in rows %}<tr class="r">{% for column in columns %}<td>{% include \'Cell\' %}</td>{% endfor %}</tr>{% endfor %}</tbody></table>',
    Cell: '{% if column.primary %}<a href="/record/?id={{ row.id }}">{{ row.name }}</a>{% else %}{{ row[column.name] }}{% endif %}',
  };
  const html =
    '<table class="grid" id="grid"><tbody><tr class="r"><td><a href="/record/?id=1">One</a></td><td>Ten</td></tr></tbody></table>';
  const result = alignResponse(html, prepare(sources), {
    resolve: (token) => (token.name === 'include' ? 'Cell' : null),
  });
  const link = result.bindings.find((binding) => binding.tag === 'a');
  assert.deepEqual(
    [link.mapping, link.sourceRefId, sources.Cell.slice(link.region.start, link.region.end), link.placement],
    ['aligned', 'Cell', '<a href="/record/?id={{ row.id }}">', 'bracketed'],
  );
  assert.deepEqual(
    link.contexts.map((context) => [context.sourceRefId, sources.Grid.slice(context.region.start, context.region.end)]),
    [['Grid', "{% include 'Cell' %}"]],
  );
});

test('a script element whose text two fields hold, inside code of a placed source, is that code’s', () => {
  const script = "(function () { 'use strict'; document.title = 'Invented form ready'; })();";
  const prepared = prepare({
    Page: '<main id="content" class="wrapper"><h1 class="title">Form</h1>{% entityform name: \'Invented\' %}<p class="after" id="after">After</p></main>',
  });
  prepared.raw = [
    { id: 'FormA', tag: 'script', tier: 1, dynamic: false, pieces: [script], length: script.length },
    { id: 'FormB', tag: 'script', tier: 1, dynamic: false, pieces: [script], length: script.length },
  ];
  const html = `<main id="content" class="wrapper"><h1 class="title">Form</h1><form id="f"><script>${script}</script></form><p class="after" id="after">After</p></main>`;
  const tag = alignResponse(html, prepared).bindings.find((binding) => binding.tag === 'script');
  assert.deepEqual([tag.mapping, tag.sourceRefId], ['generated', 'Page']);
  const alone = alignResponse(`<body><script>${script}</script></body>`, prepared).bindings.find(
    (binding) => binding.tag === 'script',
  );
  assert.deepEqual([alone.mapping, alone.sourceRefIds], ['conflict', ['FormA', 'FormB']]);
});
